SELECT  coalesce((json_agg("root" )->0), 'null' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.root.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "root" FROM  (SELECT  *  FROM "public"."author"  WHERE (("public"."author"."id") = (('1')::integer))     ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."articles" ORDER BY "ob_col_1" ASC NULLS LAST), '[]' )  FROM  (SELECT  "_unnest_table"."articles" AS "articles", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("articles" ), array_agg("root.ar.root.articles.pg.id" )) AS "_unnest_table"("articles", "ob_col_1")    ORDER BY "ob_col_1" ASC NULLS LAST LIMIT 0 ) AS "_sub_query"      ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.base"."id" AS "id"       ) AS "_e"      ) ) AS "articles", "_root.ar.root.articles.base"."id" AS "root.ar.root.articles.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.ar.root.articles.base"    ORDER BY "root.ar.root.articles.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.articles"      ) AS "_root.ar.root.articles" ON ('true')      ) AS "_root"      
